namespace PostProcessing.Metrics
{
    using System;
    using System.Collections.Generic;
    using System.Linq;
    using Utils;

    /// <summary>
    /// A class that helps to calculate PRCurve based on a predicted validation/test set.
    /// </summary>
    public static class PRCurve
    {
        /// <summary>
        /// Calculates a PRCurve.
        /// </summary>
        /// <param name="data">a list of {score, label} generated by predicting a validation set.</param>
        /// <returns>a PRCurve in the form of {threshold, recall, precision}.</returns>
        public static List<Tuple<double, SimpleMetric>> GetPRCurve(IEnumerable<Tuple<double, bool>> data)
        {
            var sortedByScore = data.OrderBy(tuple => tuple.Item1).ToList();

            var scores = new List<double>();
            for (int i = 0; i < sortedByScore.Count; i++)
            {
                if (i == 0 || GenericHelper.CompareDouble(scores.Last(), sortedByScore[i].Item1) < 0)
                {
                    scores.Add(sortedByScore[i].Item1);
                }
            }

            var thresholds = new List<double>
            {
                scores.First() - 1e-3
            };

            for (int i = 0; i + 1 < scores.Count; i++)
            {
                var th = (scores[i] + scores[i + 1]) / 2.0;
                if (GenericHelper.CompareDouble(thresholds.Last(), th) < 0)
                {
                    thresholds.Add(th);
                }
            }

            var res = new List<Tuple<double, SimpleMetric>>();
            foreach (var threshold in thresholds)
            {
                var pr = new SimpleMetric();
                foreach (var item in sortedByScore)
                {
                    pr.Update(item.Item1 > threshold, item.Item2, 1);
                }

                res.Add(Tuple.Create(threshold, pr));
            }

            return res;
        }
    }
}